// driver of test_bridge.py: plays the guest side of the COM bridge. A "guest call" reads the key at [[face] + 4 * slot], maps it to the bridge row
// (rows.gen.h, generated by the test from d9bridge_rows.tsv) and calls the row's native symbol with the stack slots as arguments.
#include <stdio.h>
#include <string.h>
#include "d9impl.gen.h"
#include "face.h"
#include "d3d9_adapter.h"
#include "rows.gen.h"   // struct Row { const char* dll; const char* name; uint32_t ordinal; void* fn; }; static const Row g_rows[]; G_NROWS
extern "C" uint32_t nx_bridge_init(void);
static int g_hide = -1;   // row hidden from the import table (part c)
extern "C" uint32_t fnvnx_import_key(const char* dll, const char* name, uint32_t ordinal) {
    for (uint32_t i = 0; i < G_NROWS; i++) if (!strcmp(g_rows[i].dll, dll) && !strcmp(g_rows[i].name, name)) return (int)i == g_hide ? 0 : 0x00100000u + 16u * i;
    return 0;
}
NxEnvProfile nx_env_profile() { return NX_ENV_HANDHELD; }
static int fails, checks; static const char* part = "a";
#define CHECK(...) do { checks++; if (!(__VA_ARGS__)) { fails++; printf("FAIL %s: %s (line %d)\n", part, #__VA_ARGS__, __LINE__); } } while (0)
static const Row* row_at(void* face, uint32_t slot) {
    uint32_t key = ((uint32_t*)(uintptr_t)*(uint32_t*)face)[slot];
    if (key < 0x00100000u || (key - 0x00100000u) % 16u || (key - 0x00100000u) / 16u >= G_NROWS) return nullptr;
    return &g_rows[(key - 0x00100000u) / 16u];
}
template <class R, class... A> static R gcall(void* face, uint32_t slot, A... a) { return ((R (*)(void*, A...))row_at(face, slot)->fn)(face, a...); }
static void* exp_fn(const char* n) { for (uint32_t i = 0; i < G_NROWS; i++) if (!strcmp(g_rows[i].dll, "d3d9.dll") && !strcmp(g_rows[i].name, n)) return g_rows[i].fn; return nullptr; }
static void done(const char* next) { printf("PART %s: %d checks, %d failed\n", part, checks, fails); part = next; checks = 0; fails = 0; }
int main(int argc, char** argv) {
    if (argc > 1) {   // part c: one row missing from the import table -> init reports it, the class gets no table from a half-filled build
        g_hide = 0; CHECK(nx_bridge_init() == 1); done("-"); return 0;
    }
    CHECK(nx_bridge_init() == 0);
    void* d3d = ((void* (*)(UINT))exp_fn("Direct3DCreate9"))(32);
    CHECK(d3d != nullptr);
    const Row* r = row_at(d3d, 0); CHECK(r && !strcmp(r->dll, "!IDirect3D9") && !strcmp(r->name, "QueryInterface") && r->ordinal == 0);
    r = row_at(d3d, 4); CHECK(r && !strcmp(r->name, "GetAdapterCount") && r->ordinal == 4);
    CHECK(gcall<ULONG>(d3d, 1) == 2); CHECK(gcall<ULONG>(d3d, 2) == 1);                       // AddRef / Release through keys
    CHECK(gcall<UINT>(d3d, 4) == 1);                                                           // GetAdapterCount of the profile
    static const GUID iid9 = {0x81bdcbca, 0x64d4, 0x426d, {0xae, 0x8d, 0xad, 0x01, 0x47, 0xf4, 0x27, 0x5c}}, bad = {1, 2, 3, {4}};
    void* q = (void*)1; CHECK(gcall<HRESULT, const GUID*, void**>(d3d, 0, &iid9, &q) == S_OK); CHECK(q == d3d);   // out handle comes back as the SAME face (identity rule)
    CHECK(gcall<ULONG>(d3d, 2) == 1);
    q = (void*)1; CHECK(gcall<HRESULT, const GUID*, void**>(d3d, 0, &bad, &q) == E_NOINTERFACE); CHECK(q == nullptr);
    CHECK((uint8_t*)nx_unface(d3d) - (uint8_t*)d3d == NX_FACE_SIZE); CHECK(nx_face((IUnknown*)nx_unface(d3d)) == d3d); CHECK(nx_face(nullptr) == nullptr && nx_unface(nullptr) == nullptr);
    void* ex = nullptr; CHECK(((HRESULT (*)(UINT, void**))exp_fn("Direct3DCreate9Ex"))(32, &ex) == S_OK && ex);
    r = row_at(ex, 4); CHECK(r && !strcmp(r->dll, "!IDirect3D9Ex") && !strcmp(r->name, "GetAdapterCount"));   // the object's own class table, also when used as IDirect3D9
    r = row_at(ex, 17); CHECK(r && !strcmp(r->dll, "!IDirect3D9Ex") && r->ordinal == 17);
    q = nullptr; CHECK(gcall<HRESULT, const GUID*, void**>(ex, 0, &iid9, &q) == S_OK && q == ex); gcall<ULONG>(ex, 2);
    CHECK(gcall<ULONG>(ex, 2) == 0); CHECK(gcall<ULONG>(d3d, 2) == 0);
    done("b");
    // b: every key table is complete and maps slot s to the row (class dll, ordinal s)
    for (uint32_t i = 0; i < G_NROWS; i++) if (g_rows[i].dll[0] == '!') { CHECK(g_rows[i].fn != nullptr); CHECK(fnvnx_import_key(g_rows[i].dll, g_rows[i].name, g_rows[i].ordinal) == 0x00100000u + 16u * i); }
    done("-");
    return 0;
}
